def mixed(catalog):
    arrays = [v.split(';') for v in catalog.values()]
    assert all(len(a) == 64 for a in arrays), [(k, len(v.split(';'))) for k, v in catalog.items()]
    # Every neighboring painting comes from another subject family.
    return [a[row] for row in range(64) for a in arrays]

